test("EN1992 every populated and absent semantic family has independent exact cell limits",async()=>{
 const cases=[{source:snapshot(),rows:fixture.semanticCells.fullRows},...fixture.binary64Words.map(word=>({source:snapshot(BigInt("0x"+word)),rows:fixture.semanticCells.fullRows}))],absent=snapshot();for(const m of absent.members){m.stirrups=null;m.punching=null;m.prestress=null;m.fire=null;m.tightness=null;}cases.push({source:absent,rows:fixture.semanticCells.absentRows});
 for(const {source,rows}of cases){
  const database=await project(source),db=sql(await exportSqliteDatabase(database));let bytes:number;
  try{expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(db.query("PRAGMA foreign_key_check").all()).toEqual([]);const tables=db.query("SELECT name FROM sqlite_schema WHERE type='table' ORDER BY name").all().map(({name})=>{const columns=db.query('PRAGMA table_info('+name+')').all(),expression=columns.map(({name})=>{const c='"'+name.replaceAll('"','""')+'"';return "CASE typeof("+c+") WHEN 'integer' THEN 8 WHEN 'real' THEN 8 WHEN 'text' THEN length(CAST("+c+" AS BLOB)) WHEN 'blob' THEN length("+c+") WHEN 'null' THEN 0 ELSE NULL END"}).join('+'),r=db.query('SELECT COUNT(*) AS rows,COALESCE(SUM('+expression+'),0) AS bytes FROM '+name).get();return{table:name,columns:columns.length,rows:Number(r.rows),semanticBytes:Number(r.bytes)}});
   expect(tables.map(t=>[t.table,t.columns])).toEqual(fixture.semanticCells.tableWidths);expect(tables.reduce((n,t)=>n+t.rows,0)).toBe(rows);bytes=tables.reduce((n,t)=>n+t.semanticBytes,0);
  }finally{db.close()}
  const exact={maxRows:rows,maxValueBytes:bytes};expect(await project(source,exact)).toEqual(database);expect(await restore(database,exact)).toEqual(source);
  for(const short of[{maxRows:rows-1,maxValueBytes:bytes},{maxRows:rows,maxValueBytes:bytes-1}]){await expect(project(source,short)).rejects.toThrow();await expect(restore(database,short)).rejects.toThrow();}
 }
