use super::En1992Snapshot;
use store::{ArtifactSqliteSnapshot,sqlite_snapshot::*};
fn fixture()->En1992Snapshot{let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();serde_json::from_value(f["snapshot"].clone()).unwrap()}
