test("Procedure complete three-table cells have independent exact and one-short limits",async()=>{
 const edited=structuredClone(corpus.snapshot);edited.schema=corpus.editedSchema;edited.text.target.artifactId=corpus.editedTarget;
 for(const source of[corpus.snapshot,edited]){
  const database=await procedureSnapshotToSqliteDatabase(source),db=Database.deserialize(await exportSqliteDatabase(database),{safeIntegers:true});let bytes:number;
  try{expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(db.query("PRAGMA foreign_key_check").all()).toEqual([]);const tables=db.query("SELECT name FROM sqlite_schema WHERE type='table' ORDER BY name").all().map(({name})=>{const columns=db.query('PRAGMA table_info('+name+')').all(),expression=columns.map(({name})=>{const c='"'+name.replaceAll('"','""')+'"';return "CASE typeof("+c+") WHEN 'integer' THEN 8 WHEN 'real' THEN 8 WHEN 'text' THEN length(CAST("+c+" AS BLOB)) WHEN 'blob' THEN length("+c+") WHEN 'null' THEN 0 ELSE NULL END"}).join('+'),r=db.query('SELECT COUNT(*) AS rows,COALESCE(SUM('+expression+'),0) AS bytes FROM '+name).get();return{table:name,columns:columns.length,rows:Number(r.rows),semanticBytes:Number(r.bytes)}});
   expect(tables.map(t=>[t.table,t.columns])).toEqual(corpus.semanticCells.tableWidths);expect(tables.reduce((n,t)=>n+t.rows,0)).toBe(corpus.semanticCells.rows);bytes=tables.reduce((n,t)=>n+t.semanticBytes,0);
   const texts=[source.schema,...[source.flow,source.text].flatMap(c=>[c.childId,c.target.artifactId,c.target.dialect.artifactKind,c.target.dialect.standard,c.target.dialect.subset])];expect(bytes).toBe(24+texts.reduce((n,text)=>n+new TextEncoder().encode(text).length,0));
  }finally{db.close()}
  const exact={maxRows:3,maxValueBytes:bytes};expect(await procedureSnapshotToSqliteDatabase(source,exact)).toEqual(database);expect(await procedureSnapshotFromSqliteDatabase(database,exact)).toEqual(source);
  for(const short of[{maxRows:2,maxValueBytes:bytes},{maxRows:3,maxValueBytes:bytes-1}]){await expect(procedureSnapshotToSqliteDatabase(source,short)).rejects.toThrow();await expect(procedureSnapshotFromSqliteDatabase(database,short)).rejects.toThrow();}
 }
