#[test]fn sqlite_snapshot_procedure_independent_sqlite_queries_and_owned_edit(){use std::io::Write;use std::process::{Command,Stdio};let s=fixture();let bytes=export_sqlite_database(&project(&s),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const n=d.query('SELECT child_id,artifact_id FROM procedure_text_child').get();if(n.child_id===n.artifact_id)throw Error('distinct target');d.query(\"UPDATE procedure_document SET schema_id='independent procedure schema 日本'\").run();d.query(\"UPDATE procedure_text_child SET artifact_id='independent seed target β'\").run();await Bun.write(Bun.stdout,d.serialize());d.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let back=restore(&import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(back.schema,"independent procedure schema 日本");assert_eq!(back.text.target.artifact_id,"independent seed target β");assert_eq!(back.text.child_id,s.text.child_id);assert_eq!(back.flow,s.flow);}
